def solve(g):
    R,C=len(g),len(g[0])
    grid=[row[:] for row in g]
    # rays: list of [r,c,dr,dc, alive, painted_cells]
    rays=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==2:
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<R and 0<=nc<C and g[nr][nc]==0:
                        rays.append([nr,nc,dr,dc,True,[]])
    while True:
        active=[x for x in rays if x[4]]
        if not active: break
        # target cells this round
        from collections import defaultdict
        targets=defaultdict(list)
        for x in active:
            targets[(x[0],x[1])].append(x)
        progressed=False
        for (cell,xs) in targets.items():
            r,c=cell
            cur=grid[r][c]
            if cur==0:
                grid[r][c]=3
                for x in xs: x[5].append(cell)
                progressed=True
                # rays continue
            elif cur in (2,3):
                for x in xs: x[4]=False
        # stop rays whose next cell is now nonzero or out of bounds
        for x in rays:
            if not x[4]: continue
            r,c=x[0],x[1]
            if grid[r][c]!=0:  # painted by another ray this round
                x[4]=False
                continue
            nr,nc=r+x[2],c+x[3]
            if not (0<=nr<R and 0<=nc<C):
                x[4]=False
                # invalid: revert its paintings (unless also painted by other ray or overlapping)
                own=[cell for cell in x[5] if len([y for y in rays if cell in y[5]])==1]
                for (rr,cc) in own:
                    grid[rr][cc]=0
                x[5]=[]
                continue
            x[0],x[1]=nr,nc
        if not progressed:
            # rays stuck pointing at nonzero cells? mark stopped
            for x in rays:
                if x[4] and grid[x[0]][x[1]]!=0: x[4]=False
            if all(not x[4] for x in rays): break
    return grid

