from collections import defaultdict

def solve(g):
    R,C=len(g),len(g[0])
    grid=[row[:] for row in g]
    rays=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==2:
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<R and 0<=nc<C and g[nr][nc]==0:
                        rays.append({'p':(nr,nc),'d':(dr,dc),'alive':True,'painted':[]})
    def cell_owners(cell):
        return [x for x in rays if cell in x['painted']]
    changed=True
    while changed:
        changed=False
        # advance rounds while any active
        while any(x['alive'] for x in rays):
            tg=defaultdict(list)
            for x in rays:
                if x['alive']: tg[x['p']].append(x)
            newly=set()
            for cell,xs in tg.items():
                r,c=cell
                if grid[r][c]==0:
                    grid[r][c]=3; newly.add(cell)
                    for x in xs: x['painted'].append(cell)
                else:
                    for x in xs: x['alive']=False
            for x in rays:
                if not x['alive']: continue
                r,c=x['p']
                if (r,c) in newly:
                    nr,nc=r+x['d'][0],c+x['d'][1]
                    if 0<=nr<R and 0<=nc<C and grid[nr][nc]==0:
                        x['p']=(nr,nc)
                    else:
                        x['alive']=False
                        if not (0<=nr<R and 0<=nc<C):
                            x['dead']=True  # hit edge: withdrawn
        # cleanup: withdraw rays that hit edge, remove their solely-owned cells, resume rays stopped on removed cells
        edge_dead=[x for x in rays if not x['alive'] and x.get('dead')]
        if edge_dead:
            changed=True
            for x in edge_dead: x['dead']='done'
            for x in edge_dead:
                for cell in x['painted']:
                    if all(y in edge_dead or y not in rays for y in cell_owners(cell)):
                        if grid[cell[0]][cell[1]]==3:
                            grid[cell[0]][cell[1]]=0
            # resume: nothing needed; withdrawn rays stay dead; but rays stopped on removed cells
            # rays stop implicitly each round, so they will just continue next round if their cell is 0 again
            for x in rays:
                if x.get('dead')=='done': continue
                if not x['alive']:
                    r,c=x['p']
                    if grid[r][c]==0 and g[r][c]==0 and cell_owners((r,c))==[]:
                        x['alive']=True  # resume from current cell
                        x['dead']=False
    return grid

